  1→package transcript
  2→
  3→import (
  4→	"bufio"
  5→	"bytes"
  6→	"encoding/json"
  7→	"fmt"
  8→	"io"
  9→	"strings"
 10→	"time"
 11→
 12→	"github.com/entireio/cli/cmd/entire/cli/textutil"
 13→)
 14→
 15→// droppedTypes are entry types that carry no parser-relevant data.
 16→var droppedTypes = map[string]bool{
 17→	"progress":              true,
 18→	"file-history-snapshot": true,
 19→	"queue-operation":       true,
 20→	"system":                true,
 21→}
 22→
 23→// CompactOptions provides metadata fields written to every output line.
 24→type CompactOptions struct {
 25→	Agent      string // e.g. "claude-code"
 26→	CLIVersion string // e.g. "0.42.0"
 27→	StartLine  int    // checkpoint_transcript_start (0 = no truncation)
 28→}
 29→
 30→// compactMeta holds pre-computed JSON fragments for fields that are identical
 31→// on every output line, avoiding repeated marshaling.
 32→type compactMeta struct {
 33→	v          json.RawMessage
 34→	agent      json.RawMessage
 35→	cliVersion json.RawMessage
 36→}
 37→
 38→func newCompactMeta(opts CompactOptions) compactMeta {
 39→	return compactMeta{
 40→		v:          mustMarshal(1),
 41→		agent:      mustMarshal(opts.Agent),
 42→		cliVersion: mustMarshal(opts.CLIVersion),
 43→	}
 44→}
 45→
 46→// Compact converts a full.jsonl transcript into the transcript.jsonl format.
 47→//
 48→// The output format puts version, agent, and cli_version on every line,
 49→// flattens the message wrapper, and splits user tool results into separate entries:
 50→//
 51→//	{"v":1,"agent":"claude-code","cli_version":"0.42.0","type":"user","ts":"...","content":"..."}
 52→//	{"v":1,"agent":"claude-code","cli_version":"0.42.0","type":"user_tool_result","ts":"...","tool_use_id":"...","result":{...}}
 53→//	{"v":1,"agent":"claude-code","cli_version":"0.42.0","type":"assistant","ts":"...","id":"msg_xxx","content":[...]}
 54→func Compact(content []byte, opts CompactOptions) ([]byte, error) {
 55→	truncated := SliceFromLine(content, opts.StartLine)
 56→	if truncated == nil {
 57→		truncated = []byte{}
 58→	}
 59→
 60→	// Detect OpenCode format: a single JSON object with "info" and "messages" keys.
 61→	if isOpenCodeFormat(truncated) {
 62→		return compactOpenCode(truncated, opts)
 63→	}
 64→
 65→	meta := newCompactMeta(opts)
 66→	reader := bufio.NewReader(bytes.NewReader(truncated))
 67→	var result []byte
 68→
 69→	for {
 70→		lineBytes, err := reader.ReadBytes('\n')
 71→		if err != nil && err != io.EOF {
 72→			return nil, err
 73→		}
 74→
 75→		if len(bytes.TrimSpace(lineBytes)) > 0 {
 76→			outputLines := convertLine(lineBytes, meta)
 77→			for _, ol := range outputLines {
 78→				result = append(result, ol...)
 79→				result = append(result, '\n')
 80→			}
 81→		}
 82→
 83→		if err == io.EOF {
 84→			break
 85→		}
 86→	}
 87→
 88→	return result, nil
 89→}
 90→
 91→// userAliases maps transcript type/role values to the canonical "user" kind.
 92→var userAliases = map[string]bool{
 93→	TypeUser: true,
 94→	"human":  true,
 95→}
 96→
 97→// assistantAliases maps transcript type/role values to the canonical "assistant" kind.
 98→var assistantAliases = map[string]bool{
 99→	TypeAssistant: true,
100→	"gemini":      true,
101→}
102→
103→// normalizeKind returns the canonical entry kind ("user" or "assistant") for a
104→// transcript line. It checks the "type" field, then falls back to "role".
105→// Returns "" for unrecognised or dropped entries.
106→func normalizeKind(raw map[string]json.RawMessage) string {
107→	kind := unquote(raw["type"])
108→	if kind == "" {
109→		kind = unquote(raw["role"])
110→	}
111→
112→	if droppedTypes[kind] {
113→		return ""
114→	}
115→	if userAliases[kind] {
116→		return TypeUser
117→	}
118→	if assistantAliases[kind] {
119→		return TypeAssistant
120→	}
121→	return ""
122→}
123→
124→// unwrapEnvelope handles envelope formats where the actual message is nested.
125→// Factory AI Droid uses {"type":"message","message":{"role":"user","content":...}}.
126→// If the line is an envelope, it promotes inner fields (role, content) to the top
127→// level and carries over outer fields (timestamp, id) so converters see a flat structure.
128→// Otherwise it returns raw unchanged.
129→func unwrapEnvelope(raw map[string]json.RawMessage) map[string]json.RawMessage {
130→	if unquote(raw["type"]) != "message" {
131→		return raw
132→	}
133→
134→	msgRaw, ok := raw["message"]
135→	if !ok {
136→		return raw
137→	}
138→
139→	var inner map[string]json.RawMessage
140→	if json.Unmarshal(msgRaw, &inner) != nil {
141→		return raw
142→	}
143→
144→	innerRole := unquote(inner["role"])
145→	if !userAliases[innerRole] && !assistantAliases[innerRole] {
146→		return raw
147→	}
148→
149→	// Merge outer → inner: outer timestamp/id as defaults, inner fields override.
150→	merged := make(map[string]json.RawMessage, len(inner)+3)
151→	if v, has := raw["timestamp"]; has {
152→		merged["timestamp"] = v
153→	}
154→	if v, has := raw["id"]; has {
155→		merged["id"] = v
156→	}
157→	for k, v := range inner {
158→		merged[k] = v
159→	}
160→	// Promote "role" to "type" so normalizeKind resolves it.
161→	if _, hasType := merged["type"]; !hasType {
162→		merged["type"] = inner["role"]
163→	}
164→	// Keep "message" so converters can extract nested content.
165→	merged["message"] = msgRaw
166→
167→	return merged
168→}
169→
170→// convertLine converts a single full.jsonl line into zero or more transcript.jsonl lines.
171→func convertLine(lineBytes []byte, meta compactMeta) [][]byte {
172→	var raw map[string]json.RawMessage
173→	if err := json.Unmarshal(lineBytes, &raw); err != nil {
174→		return nil
175→	}
176→
177→	raw = unwrapEnvelope(raw)
178→
179→	switch normalizeKind(raw) {
180→	case TypeAssistant:
181→		return convertAssistant(raw, meta)
182→	case TypeUser:
183→		return convertUser(raw, meta)
184→	default:
185→		return nil
186→	}
187→}
188→
189→func convertAssistant(raw map[string]json.RawMessage, meta compactMeta) [][]byte {
190→	var id, content json.RawMessage
191→	if msg := parseMessage(raw); msg != nil {
192→		id = msg["id"]
193→		if contentRaw, ok := msg["content"]; ok {
194→			content = stripAssistantContent(contentRaw)
195→		}
196→	}
197→
198→	b := marshalOrdered(
199→		"v", meta.v,
200→		"agent", meta.agent,
201→		"cli_version", meta.cliVersion,
202→		"type", mustMarshal(TypeAssistant),
203→		"ts", raw["timestamp"],
204→		"id", id,
205→		"content", content,
206→	)
207→	if b == nil {
208→		return nil
209→	}
210→	return [][]byte{b}
211→}
212→
213→func convertUser(raw map[string]json.RawMessage, meta compactMeta) [][]byte {
214→	var lines [][]byte
215→	ts := raw["timestamp"]
216→
217→	var textContent string
218→	var toolResults []toolResultEntry
219→
220→	if msg := parseMessage(raw); msg != nil {
221→		if contentRaw, ok := msg["content"]; ok {
222→			textContent, toolResults = extractUserContent(contentRaw)
223→		}
224→	}
225→
226→	b := marshalOrdered(
227→		"v", meta.v,
228→		"agent", meta.agent,
229→		"cli_version", meta.cliVersion,
230→		"type", mustMarshal(TypeUser),
231→		"ts", ts,
232→		"content", mustMarshal(textContent),
233→	)
234→	if b != nil {
235→		lines = append(lines, b)
236→	}
237→
238→	// full.jsonl has a single toolUseResult per user entry, not one per tool_use_id.
239→	// When there are multiple tool_result blocks, each user_tool_result line gets the
240→	// same minimized result — a known limitation of the source format.
241→	var minimizedResult json.RawMessage
242→	if turRaw, ok := raw["toolUseResult"]; ok {
243→		minimizedResult = minimizeToolUseResult(turRaw)
244→	}
245→
246→	for _, tr := range toolResults {
247→		result := minimizedResult
248→		if result == nil {
249→			result = mustMarshal(map[string]interface{}{})
250→		}
251→
252→		b := marshalOrdered(
253→			"v", meta.v,
254→			"agent", meta.agent,
255→			"cli_version", meta.cliVersion,
256→			"type", mustMarshal("user_tool_result"),
257→			"ts", ts,
258→			"tool_use_id", mustMarshal(tr.toolUseID),
259→			"result", result,
260→		)
261→		if b != nil {
262→			lines = append(lines, b)
263→		}
264→	}
265→
266→	return lines
267→}
268→
269→type toolResultEntry struct {
270→	toolUseID string
271→}
272→
273→// parseMessage extracts and parses the "message" field from a transcript line.
274→func parseMessage(raw map[string]json.RawMessage) map[string]json.RawMessage {
275→	msgRaw, ok := raw["message"]
276→	if ok {
277→		var msg map[string]json.RawMessage
278→		if json.Unmarshal(msgRaw, &msg) == nil {
279→			return msg
280→		}
281→	}
282→
283→	// Native Gemini transcript entries store id/content at top-level
284→	// rather than inside a nested "message" object.
285→	msg := make(map[string]json.RawMessage, 2)
286→	if v, has := raw["id"]; has {
287→		msg["id"] = v
288→	}
289→	if v, has := raw["content"]; has {
290→		msg["content"] = v
291→	}
292→	if len(msg) == 0 {
293→		return nil
294→	}
295→	return msg
296→}
297→
298→// extractUserContent separates user message content into text and tool_result entries.
299→// IDE context tags (e.g. <user_query>, <ide_opened_file>) are stripped from user text.
300→func extractUserContent(contentRaw json.RawMessage) (string, []toolResultEntry) {
301→	var str string
302→	if json.Unmarshal(contentRaw, &str) == nil {
303→		return textutil.StripIDEContextTags(str), nil
304→	}
305→
306→	var blocks []map[string]json.RawMessage
307→	if json.Unmarshal(contentRaw, &blocks) != nil {
308→		return "", nil
309→	}
310→
311→	var texts []string
312→	var toolResults []toolResultEntry
313→
314→	for _, block := range blocks {
315→		blockType := unquote(block["type"])
316→
317→		if blockType == "tool_result" {
318→			toolResults = append(toolResults, toolResultEntry{
319→				toolUseID: unquote(block["tool_use_id"]),
320→			})
321→			continue
322→		}
323→
324→		if blockType == ContentTypeText {
325→			stripped := textutil.StripIDEContextTags(unquote(block[ContentTypeText]))
326→			if stripped != "" {
327→				texts = append(texts, stripped)
328→			}
329→		}
330→	}
331→
332→	return strings.Join(texts, "\n\n"), toolResults
333→}
334→
335→func stripAssistantContent(contentRaw json.RawMessage) json.RawMessage {
336→	var str string
337→	if json.Unmarshal(contentRaw, &str) == nil {
338→		return contentRaw
339→	}
340→
341→	var blocks []map[string]json.RawMessage
342→	if json.Unmarshal(contentRaw, &blocks) != nil {
343→		return contentRaw
344→	}
345→
346→	result := make([]map[string]json.RawMessage, 0, len(blocks))
347→	for _, block := range blocks {
348→		blockType := unquote(block["type"])
349→
350→		if blockType == "thinking" || blockType == "redacted_thinking" {
351→			continue
352→		}
353→
354→		if blockType == ContentTypeToolUse {
355→			stripped := make(map[string]json.RawMessage)
356→			copyField(stripped, block, "type")
357→			copyField(stripped, block, "id")
358→			copyField(stripped, block, "name")
359→			copyField(stripped, block, "input")
360→			result = append(result, stripped)
361→			continue
362→		}
363→
364→		result = append(result, block)
365→	}
366→
367→	b, err := json.Marshal(result)
368→	if err != nil {
369→		return contentRaw
370→	}
371→	return b
372→}
373→
374→// minimizeToolUseResult keeps only fields needed for replaying tool calls
375→// (type, file metadata, error, answers). Output text and other verbose
376→// fields are dropped to reduce transcript size.
377→func minimizeToolUseResult(raw json.RawMessage) json.RawMessage {
378→	var obj map[string]json.RawMessage
379→	if json.Unmarshal(raw, &obj) != nil {
380→		return raw
381→	}
382→
383→	return marshalOrdered(
384→		"type", obj["type"],
385→		"file", obj["file"],
386→		"error", obj["error"],
387→		"answers", obj["answers"],
388→	)
389→}
390→
391→// marshalOrdered produces a JSON object with keys in the given order.
392→// Pairs with nil values are omitted.
393→func marshalOrdered(pairs ...interface{}) []byte {
394→	var buf bytes.Buffer
395→	buf.WriteByte('{')
396→	first := true
397→	for i := 0; i < len(pairs)-1; i += 2 {
398→		key := pairs[i].(string)
399→		val, _ := pairs[i+1].(json.RawMessage)
400→		if val == nil {
401→			continue
402→		}
403→		if !first {
404→			buf.WriteByte(',')
405→		}
406→		keyJSON, _ := json.Marshal(key)
407→		buf.Write(keyJSON)
408→		buf.WriteByte(':')
409→		buf.Write(val)
410→		first = false
411→	}
412→	buf.WriteByte('}')
413→	return buf.Bytes()
414→}
415→
416→func mustMarshal(v interface{}) json.RawMessage {
417→	b, _ := json.Marshal(v)
418→	return b
419→}
420→
421→func copyField(dst, src map[string]json.RawMessage, key string) {
422→	if v, ok := src[key]; ok {
423→		dst[key] = v
424→	}
425→}
426→
427→func unquote(raw json.RawMessage) string {
428→	var s string
429→	if json.Unmarshal(raw, &s) == nil {
430→		return s
431→	}
432→	return ""
433→}
434→
435→// --- OpenCode format support ---
436→//
437→// OpenCode transcripts are a single JSON object (not JSONL):
438→//
439→//	{"info":{...},"messages":[{"info":{"role":"user","time":{...}},"parts":[...]}, ...]}
440→//
441→// Parts use "type" values: "text", "tool", "step-start", "step-finish".
442→// Tool parts store the tool name in "tool" (string) and call details in "state".
443→
444→// isOpenCodeFormat checks whether content is a single JSON object with the
445→// OpenCode session shape (top-level "info" and "messages" keys).
446→func isOpenCodeFormat(content []byte) bool {
447→	trimmed := bytes.TrimSpace(content)
448→	if len(trimmed) == 0 || trimmed[0] != '{' {
449→		return false
450→	}
451→	// Quick structural check: unmarshal just enough to detect the keys.
452→	var probe struct {
453→		Info     *json.RawMessage `json:"info"`
454→		Messages *json.RawMessage `json:"messages"`
455→	}
456→	if json.Unmarshal(trimmed, &probe) != nil {
457→		return false
458→	}
459→	return probe.Info != nil && probe.Messages != nil
460→}
461→
462→// openCodeMessage mirrors the OpenCode message structure for unmarshaling.
463→type openCodeMessage struct {
464→	Info  openCodeMessageInfo      `json:"info"`
465→	Parts []map[string]json.RawMessage `json:"parts"`
466→}
467→
468→type openCodeMessageInfo struct {
469→	ID   string          `json:"id"`
470→	Role string          `json:"role"`
471→	Time openCodeMsgTime `json:"time"`
472→}
473→
474→type openCodeMsgTime struct {
475→	Created   int64 `json:"created"`
476→	Completed int64 `json:"completed"`
477→}
478→
479→// compactOpenCode converts a full OpenCode session JSON into transcript lines.
480→func compactOpenCode(content []byte, opts CompactOptions) ([]byte, error) {
481→	var session struct {
482→		Messages []openCodeMessage `json:"messages"`
483→	}
484→	if err := json.Unmarshal(bytes.TrimSpace(content), &session); err != nil {
485→		return nil, fmt.Errorf("parsing opencode session: %w", err)
486→	}
487→
488→	meta := newCompactMeta(opts)
489→	var result []byte
490→
491→	for _, msg := range session.Messages {
492→		ts := msToTimestamp(msg.Info.Time.Created)
493→
494→		switch msg.Info.Role {
495→		case TypeUser:
496→			lines := convertOpenCodeUser(msg, ts, meta)
497→			for _, l := range lines {
498→				result = append(result, l...)
499→				result = append(result, '\n')
500→			}
501→		case TypeAssistant:
502→			lines := convertOpenCodeAssistant(msg, ts, meta)
503→			for _, l := range lines {
504→				result = append(result, l...)
505→				result = append(result, '\n')
506→			}
507→		}
508→	}
509→
510→	return result, nil
511→}
512→
513→func convertOpenCodeUser(msg openCodeMessage, ts json.RawMessage, meta compactMeta) [][]byte {
514→	var texts []string
515→	for _, part := range msg.Parts {
516→		if unquote(part["type"]) == ContentTypeText {
517→			text := textutil.StripIDEContextTags(unquote(part[ContentTypeText]))
518→			if text != "" {
519→				texts = append(texts, text)
520→			}
521→		}
522→	}
523→
524→	b := marshalOrdered(
525→		"v", meta.v,
526→		"agent", meta.agent,
527→		"cli_version", meta.cliVersion,
528→		"type", mustMarshal(TypeUser),
529→		"ts", ts,
530→		"content", mustMarshal(strings.Join(texts, "\n\n")),
531→	)
532→	if b == nil {
533→		return nil
534→	}
535→	return [][]byte{b}
536→}
537→
538→func convertOpenCodeAssistant(msg openCodeMessage, ts json.RawMessage, meta compactMeta) [][]byte {
539→	content := make([]map[string]json.RawMessage, 0, len(msg.Parts))
540→
541→	for _, part := range msg.Parts {
542→		partType := unquote(part["type"])
543→
544→		switch partType {
545→		case ContentTypeText:
546→			content = append(content, map[string]json.RawMessage{
547→				"type": mustMarshal(ContentTypeText),
548→				"text": part[ContentTypeText],
549→			})
550→		case "tool":
551→			toolBlock := make(map[string]json.RawMessage)
552→			toolBlock["type"] = mustMarshal(ContentTypeToolUse)
553→			if callID := part["callID"]; callID != nil {
554→				toolBlock["id"] = callID
555→			}
556→			// "tool" field is the tool name (string).
557→			if toolName := part["tool"]; toolName != nil {
558→				toolBlock["name"] = toolName
559→			}
560→			// Extract input from state.input if available.
561→			if stateRaw := part["state"]; stateRaw != nil {
562→				var state map[string]json.RawMessage
563→				if json.Unmarshal(stateRaw, &state) == nil {
564→					if inp := state["input"]; inp != nil {
565→						toolBlock["input"] = inp
566→					}
567→				}
568→			}
569→			content = append(content, toolBlock)
570→		// step-start, step-finish carry no transcript-relevant data.
571→		}
572→	}
573→
574→	contentJSON, err := json.Marshal(content)
575→	if err != nil {
576→		return nil
577→	}
578→
579→	b := marshalOrdered(
580→		"v", meta.v,
581→		"agent", meta.agent,
582→		"cli_version", meta.cliVersion,
583→		"type", mustMarshal(TypeAssistant),
584→		"ts", ts,
585→		"id", mustMarshal(msg.Info.ID),
586→		"content", json.RawMessage(contentJSON),
587→	)
588→	if b == nil {
589→		return nil
590→	}
591→	return [][]byte{b}
592→}
593→
594→// msToTimestamp converts a Unix millisecond timestamp to an RFC3339 JSON string.
595→func msToTimestamp(ms int64) json.RawMessage {
596→	if ms == 0 {
597→		return nil
598→	}
599→	t := time.UnixMilli(ms).UTC()
600→	return mustMarshal(t.Format(time.RFC3339Nano))
601→}
