 20→func TestCompact_SimpleConversation(t *testing.T) {
 21→	t.Parallel()
 22→
 23→	input := []byte(`{"type":"user","uuid":"u1","timestamp":"2026-01-01T00:00:00Z","parentUuid":"","cwd":"/repo","message":{"content":"hello"}}
 24→{"type":"assistant","timestamp":"2026-01-01T00:00:01Z","requestId":"req-1","message":{"id":"msg-1","content":[{"type":"text","text":"Hi!"}]}}
 25→`)
 26→
 27→	expected := []string{
 28→		`{"v":1,"agent":"claude-code","cli_version":"0.5.1","type":"user","ts":"2026-01-01T00:00:00Z","content":"hello"}`,
 29→		`{"v":1,"agent":"claude-code","cli_version":"0.5.1","type":"assistant","ts":"2026-01-01T00:00:01Z","id":"msg-1","content":[{"type":"text","text":"Hi!"}]}`,
 30→	}
 31→
 32→	result, err := Compact(input, defaultOpts)
 33→	if err != nil {
 34→		t.Fatalf("unexpected error: %v", err)
 35→	}
 36→	assertJSONLines(t, result, expected)
 37→}
