  "info": {"id": "ses_test123", "title": "Test session", "version": "1.2.27", "time": {"created": 1773867525006}},
  "messages": [
    {
      "info": {"id": "msg_user1", "role": "user", "sessionID": "ses_test123", "time": {"created": 1773867525015}},
      "parts": [{"type": "text", "text": "Fix the bug in main.go", "id": "p1", "messageID": "msg_user1", "sessionID": "ses_test123"}]
    },
    {
      "info": {"id": "msg_asst1", "role": "assistant", "modelID": "claude-opus-4-6", "time": {"created": 1773867530000, "completed": 1773867540000}, "tokens": {"total": 500, "input": 100, "output": 400}},
      "parts": [
        {"type": "step-start", "id": "ss1", "messageID": "msg_asst1", "sessionID": "ses_test123"},
        {"type": "text", "text": "Let me read the file first.", "id": "p2", "messageID": "msg_asst1", "sessionID": "ses_test123"},
        {"type": "tool", "callID": "toolu_abc123", "tool": "read", "state": {"status": "completed", "input": {"filePath": "/repo/main.go"}}, "id": "p3", "messageID": "msg_asst1", "sessionID": "ses_test123"},
        {"type": "tool", "callID": "toolu_def456", "tool": "edit", "state": {"status": "completed", "input": {"filePath": "/repo/main.go", "old": "bad", "new": "good"}}, "id": "p4", "messageID": "msg_asst1", "sessionID": "ses_test123"},
        {"type": "step-finish", "id": "sf1", "messageID": "msg_asst1", "sessionID": "ses_test123", "reason": "tool-calls"}
      ]
    },
    {
      "info": {"id": "msg_user2", "role": "user", "sessionID": "ses_test123", "time": {"created": 1773867545000}},
      "parts": [{"type": "text", "text": "Thanks!", "id": "p5", "messageID": "msg_user2", "sessionID": "ses_test123"}]
    }
  ]
}`)

	expected := []string{
		`{"v":1,"agent":"opencode","cli_version":"0.5.1","type":"user","ts":"2026-03-18T20:58:45.015Z","content":"Fix the bug in main.go"}`,
		`{"v":1,"agent":"opencode","cli_version":"0.5.1","type":"assistant","ts":"2026-03-18T20:58:50Z","id":"msg_asst1","content":[{"type":"text","text":"Let me read the file first."},{"type":"tool_use","id":"toolu_abc123","name":"read","input":{"filePath":"/repo/main.go"}},{"type":"tool_use","id":"toolu_def456","name":"edit","input":{"filePath":"/repo/main.go","old":"bad","new":"good"}}]}`,
		`{"v":1,"agent":"opencode","cli_version":"0.5.1","type":"user","ts":"2026-03-18T20:59:05Z","content":"Thanks!"}`,
	}

	result, err := Compact(input, openCodeOpts)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	assertJSONLines(t, result, expected)
}

func TestCompact_OpenCodeEmptyMessages(t *testing.T) {
	t.Parallel()

	openCodeOpts := CompactOptions{
		Agent:      "opencode",
		CLIVersion: "0.5.1",
		StartLine:  0,
	}

	input := []byte(`{"info": {"id": "ses_empty"}, "messages": []}`)

	result, err := Compact(input, openCodeOpts)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if len(bytes.TrimSpace(result)) != 0 {
